new = '''// Reads keys/children/hops straight out of the image bytes.
inline void lookup_image(const std::string& bytes, u128 addr, Answer& out) {
    if (bytes.size() < 128) throw std::runtime_error("short image");
    const char* p = bytes.data();
    int hopoff = int(get_u32(p + 16));
    int R = int(get_u32(p + 8));
    out.path.clear();
    int off = 64;
    while (true) {
        if (off < 64 || off + 32 > hopoff) throw std::runtime_error("node out of range");
        out.path.push_back(off);
        const char* q = p + off;
        int kind = unsigned char(q[0]);
        int mode = unsigned char(q[1]);
        u128 base = get_u128(q + 16);
        int w = WIDTH[mode];
        auto readkey = [&](const char* kp, int i) -> u128 {
            const char* k = kp + size_t(i) * w;
            if (mode == 0) return get_u128(k);
            if (mode == 1) return u128(get_u64(k)) + base;
            return u128(get_u32(k)) + base;
        };
        if (kind == 1) {
            int lo = int(get_u16(q + 4));
            int span = int(get_u16(q + 6));
            const char* kp = q + 32;
            int a = 0, b = span;               // count of stored starts <= addr
            while (a < b) {
                int mid = (a + b) / 2;
                if (readkey(kp, mid) <= addr) a = mid + 1;
                else b = mid;
            }
            int idx = a - 1;
            if (idx < 0 || idx >= span) throw std::runtime_error("leaf predecessor");
            out.run = lo + idx;
            break;
        }
        int b = int(get_u16(q + 8));
        const char* cp = q + 32;
        const char* kp = cp + 4 * b;
        int a = 0, e = b - 1;                  // count of separators <= addr
        while (a < e) {
            int mid = (a + e) / 2;
            if (readkey(kp, mid) <= addr) a = mid + 1;
            else e = mid;
        }
        off = int(get_u32(cp + 4 * a));
    }
    if (out.run < 0 || out.run >= R) throw std::runtime_error("run range");
    u64 stored = get_u32(p + hopoff + 4 * out.run);
    out.hop = (stored == 0xffffffffu) ? -1 : int(stored);
}

'''
